import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
storage_ids = []
capacities = {}
for rec in capacity_records:
    sid = rec['values']['StorageID']
    storage_ids.append(sid)
    capacities[sid] = int(rec['values']['Capacity'])
product_names = []
values = {}
weights = {}
for rec in product_records:
    pname = rec['values']['ProductName']
    product_names.append(pname)
    values[pname] = int(rec['values']['Value'])
    weights[pname] = int(rec['values']['Weight'])
if len(storage_ids) != 15:
    raise ValueError('Expected 15 storage areas, got {}'.format(len(storage_ids)))
if len(product_names) != 10:
    raise ValueError('Expected 10 product types, got {}'.format(len(product_names)))
if set(capacities.keys()) != set(storage_ids):
    raise ValueError('Mismatch in storage IDs and capacities')
if set(values.keys()) != set(product_names) or set(weights.keys()) != set(product_names):
    raise ValueError('Mismatch in product names and value/weight keys')
m = gp.Model('Amazon_AC_Storage')
x_vars = m.addVars(storage_ids, product_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[j] * x_vars[i, j] for i in storage_ids for j in product_names)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weights[j] * x_vars[i, j] for j in product_names)) <= capacities[i] for i in storage_ids), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')